protocol BookingGateway {                          // domestic interface
    func slots(length: Duration) async throws -> [Slot]
}
struct HTTPBookingGateway: BookingGateway {
    let session: URLSession
    func slots(length: Duration) async throws -> [Slot] {
        let (data, response) = try await session.data(from: slotsURL(length))
        try Task.checkCancellation()                // cooperative cancellation
        return try decodeSlots(data, response)      // foreign -> domestic
    }
}

