func slots(length: Duration, completion: @escaping (Result<[Slot], BookingError>) -> Void) {
    let task = session.dataTask(with: slotsURL(length)) { data, response, error in
        if let error { return completion(.failure(.transport(error))) }
        guard let http = response as? HTTPURLResponse,
              (200..<300).contains(http.statusCode) else {
            return completion(.failure(.http((response as? HTTPURLResponse)?.statusCode)))
        }
        completion(decodeSlots(data))         // foreign -> domestic
    }
    task.resume()                             // nothing happens until resume()
}
